// Report Manager - canonical URLs and a crawlable index for the .NET reference (docnet/).
//
// WHY. On 12-11-2026 Search Console reported 306 pages «Crawled, currently not indexed» and 44
// «Discovered, currently not indexed» for reportman.es, and almost all of them are docnet/api/:
// 498 generated pages. Two things were missing, and both are ours:
//
//   * NOT ONE of the 498 carried a <link rel="canonical">. Every other URL that lands on the same
//     page --the directory form, a stray query string, the old host-- is then a page of its own to
//     a crawler, and the reference competes with itself.
//   * The only complete list of the types is toc.html, which DocFX injects WITH JAVASCRIPT. A
//     crawler that does not run it saw 13 links from /docnet/ reaching into 498 pages: 163 of them
//     had one or two inbound links in the static HTML, and /docnet/api/ itself answered 403.
//     A page that almost nothing links to is exactly what Google crawls and decides not to index.
//
// So this writes api/index.html --the same list, in plain HTML, in DocFX's own layout-- and the
// canonical of every page. It does NOT promise that Google will index 500 generated pages: a
// reference like this is thin by nature and part of it will stay out. What it fixes is the part
// that was our doing.
//
// Re-run after regenerating the reference, like docnet-namespaces.mjs:
//   node doc/_build/docnet-seo.mjs
// Idempotent: the canonical is added only where there is none, and index.html is rewritten only
// while it carries this script's marker, so a page DocFX writes later is never overwritten.

import fs from 'node:fs';
import path from 'node:path';

const DOCNET = path.resolve(import.meta.dirname, '..', 'docnet');
const APIDIR = path.join(DOCNET, 'api');
const BASE = 'https://reportman.es';
const TEMPLATE = 'Reportman.Hub.Client.DataChannel.html'; // any DocFX namespace page
const MARKER = '<!-- generated by doc/_build/docnet-seo.mjs -->';

const toc = JSON.parse(fs.readFileSync(path.join(APIDIR, 'toc.json'), 'utf-8'));
const namespaces = toc.items.filter(i => i.type === 'Namespace' && (i.items || []).length);

// ---------------------------------------------------------------- api/index.html
const plural = { Class: 'classes', Struct: 'structs', Interface: 'interfaces', Enum: 'enums', Delegate: 'delegates' };
const resumen = items => {
  const by = {};
  for (const t of items) by[t.type] = (by[t.type] || 0) + 1;
  return `${items.length} ${items.length === 1 ? 'type' : 'types'}: ` +
    Object.entries(by).map(([k, v]) => `${v} ${v === 1 ? k.toLowerCase() : (plural[k] || k.toLowerCase() + 's')}`).join(', ') + '.';
};

const destino = path.join(APIDIR, 'index.html');
const suyo = !fs.existsSync(destino) || fs.readFileSync(destino, 'utf-8').includes(MARKER);
if (!suyo) {
  console.log('docnet/api/index.html exists and is not ours: left alone.');
} else {
  const template = fs.readFileSync(path.join(APIDIR, TEMPLATE), 'utf-8');
  const EOL = template.includes('\r\n') ? '\r\n' : '\n';
  const tplName = TEMPLATE.replace(/\.html$/, '');
  const tipos = namespaces.reduce((n, ns) => n + ns.items.length, 0);
  const titulo = 'Report Manager .NET API reference';
  const desc = `Report Manager .NET API reference: every one of the ${tipos} types, by namespace `
             + `(reporting engine, drawing, Windows Forms and WPF preview, designer, Hub client).`;

  const article = [
    '<article class="content wrap" id="_content" data-uid="">',
    '',
    `  <h1 id="api-reference" class="text-break">${titulo}</h1>`,
    `  <div class="markdown level0 summary"><p>The ${tipos} public types of the Report Manager .NET`,
    `    libraries, grouped in their ${namespaces.length} namespaces. Each namespace page lists its types`,
    '    with their members; this page is the full index.</p></div>',
    '  <div class="markdown level0 conceptual"></div>',
    '  <div class="markdown level0 remarks"></div>',
    '    <h3 id="namespaces">',
    'Namespaces',
    '</h3>',
    ...namespaces.flatMap(ns => [
      `      <h4><a class="xref" href="${ns.href}">${ns.name}</a></h4>`,
      `      <section><p>${resumen(ns.items)}</p>`,
      '        <ul>',
      ...ns.items.map(t => `          <li><a class="xref" href="${t.href}">${t.name}</a> (${t.type.toLowerCase()})</li>`),
      '        </ul>',
      '      </section>',
    ]),
    '',
    '',
    '</article>',
  ].join(EOL);

  const html = template
    .replace(/<article class="content wrap"[\s\S]*?<\/article>/, '@ARTICLE@')
    // The template may already carry ITS canonical --this script put it there on an earlier run--
    // and it names the template page, which would trip the guard below. The index gets its own in
    // the canonical pass further down.
    .replace(/[ \t]*<link rel="canonical"[^>]*>\r?\n/, '')
    .split(`Namespace ${tplName}`).join(titulo)
    .replace(/(<meta name="title"[^>]*>)/, `$1${EOL}      <meta name="description" content="${desc}">`)
    .replace('<html>', `<html>${EOL}${MARKER}`);
  if (html.includes(tplName) || !html.includes('@ARTICLE@')) throw new Error('template not as expected');
  fs.writeFileSync(destino, html.replace('@ARTICLE@', () => article));
  console.log(`wrote docnet/api/index.html (${namespaces.length} namespaces, ${tipos} types)`);
}

// ------------------------------------------------- the link from /docnet/ to the index
// Without it the new page is an orphan: the sitemap would be the only thing pointing at it, and a
// URL that only the sitemap knows is a URL with no weight at all.
{
  const fichero = path.join(DOCNET, 'index.html');
  const html = fs.readFileSync(fichero, 'utf-8');
  const EOL = html.includes('\r\n') ? '\r\n' : '\n';
  const enlace = '<p><a href="api/index.html">Full type index</a> \u2014 every type of the reference, by namespace.</p>';
  if (html.includes('api/index.html')) {
    console.log('/docnet/ already links the index.');
  } else {
    const m = html.match(/(<h2 id="assemblies">[\s\S]*?<\/ul>)/);
    if (!m) throw new Error('docnet/index.html: no assemblies list to hang the link from');
    fs.writeFileSync(fichero, html.replace(m[1], `${m[1]}${EOL}${enlace}`));
    console.log('linked the index from /docnet/.');
  }
}

// ---------------------------------------------------------------- canonical
// toc.html is left out on purpose: it is not a page --it starts at <div id="sidetoggle">, with no
// <html> and no <title>-- but the side tree DocFX injects with JavaScript.
const paginas = [
  ...fs.readdirSync(APIDIR).filter(f => f.endsWith('.html') && f !== 'toc.html')
       .map(f => [path.join(APIDIR, f), `${BASE}/docnet/api/${f}`]),
  [path.join(DOCNET, 'index.html'), `${BASE}/docnet/index.html`],
];

let puestos = 0, ya = 0;
for (const [fichero, url] of paginas) {
  if (!fs.existsSync(fichero)) continue;
  const html = fs.readFileSync(fichero, 'utf-8');
  if (html.includes('rel="canonical"')) { ya++; continue; }
  const m = html.match(/^([ \t]*)<title>.*?<\/title>[ \t]*$/m);
  if (!m) { console.log(`  no <title> of its own, skipped: ${path.basename(fichero)}`); continue; }
  const EOL = html.includes('\r\n') ? '\r\n' : '\n';
  fs.writeFileSync(fichero, html.replace(m[0], `${m[0]}${EOL}${m[1]}<link rel="canonical" href="${url}">`));
  puestos++;
}
console.log(`canonical: ${puestos} added, ${ya} already had one.`);
